-- H077 Betony (Wood), temperature: the stored value hedges itself, 'Warm (mildly)', so it is not a plain Warm
do $do$
declare n int;
begin
  update public.herbs
     set temperature = 'Warm',
         last_updated = now()
   where herb_id = 'H077'
     and temperature = 'Warm (mildly)';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs
                where herb_id = 'H077' and temperature = 'Warm') then
      raise notice 'H077.temperature already corrected, skipped';
    else
      raise exception 'H077.temperature: the live value no longer matches the value this migration was built against; not updated';
    end if;
  end if;
end
$do$;

