insert into _energetics_batch6 values ('H084', $j${"agreement_state": "none", "app_value": {"moisture": "Drying", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Dutt, Materia Medica of the Hindus (1877), s.v. OLIBANUM: 'The gum of the Salai tree of India (Boswellia thurifera), is called Kunduru in Sanskrit. It is used as an incense and as a local application to buboes.' No temperature, no moisture, and the species he names is Boswellia thurifera", "Gerard 1633 and Salmon 1710: no chapter on olibanum as a drug was found; Salmon's 'Herb Frankincense' chapters are Libanotis, an umbellifer, not Boswellia", "Shennong Bencao Jing, Rajanighantu, Watt Vol. IV, Ibn al-Baytar (Leclerc Vols. I and II): no Boswellia serrata article with a thermal quality"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant and part. Frankincense is a traded resin that several Boswellia trees make, and the old books either describe that shop drug or describe the tree rather than its resin.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because readings were found but none of them counts: No pre-1900 source found for this exact plant and part. Frankincense is a traded resin that several Boswellia trees make, and the old books either describe that shop drug or describe the tree rather than its resin.", "The stored part is the resin of Boswellia serrata. Frankincense or olibanum is a traded drug that several Boswellia species make, which is the case the founder named when she set aloes aside, so every reading for the shop drug is shown and counted for nothing."], "part_used": "Resin", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Frankincense and olibanum are each named in the list, so this is not a group statement; but the drug is the shop resin, which several Boswellia species make, and Culpeper names no plant. Shown and not counted. His gum list gives no moisture, so this would be a temperature only in any case.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Gums are either temperate, as, Lacca, Elemi, Tragacanth, &c. Intemperate, and so are hot in the first degree, as Bdellium, Gum of Ivy. In the second, Galbanum, Myrrh, Mastich, Frankincense, Olibanum, Pitch, Rozin, Styrax.", "gloss": "Frankincense and olibanum are gums hot in the second degree.", "locator": "Culpeper's list of gums and rozins (Gutenberg #49513, offset ~982928)", "not_counted_why": "Frankincense and olibanum are each named in the list, so this is not a group statement; but the drug is the shop resin, which several Boswellia species make, and Culpeper names no plant. Shown and not counted. His gum list gives no moisture, so this would be a temperature only in any case.", "note": "Frankincense and olibanum are each named in the list, so this is not a group statement; but the drug is the shop resin, which several Boswellia species make, and Culpeper names no plant. Shown and not counted. His gum list gives no moisture, so this would be a temperature only in any case.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Two reasons not to count it. Dymock reports the Mahometan writers rather than giving his own reading, and his own heading says the drug comes from several species of Boswellia growing in Africa and Arabia, none of them Boswellia serrata.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Olibanum is considered by the Mahometans to be hot and dry, and to have dessicative, astringent and detergent properties.", "gloss": "Olibanum is reckoned hot and dry by the Mahometan writers.", "locator": "Vol. I (1890), 'BOSWELLIA. Several species inhabiting Eastern Africa, near Cape Guardafui, Socotra and the Southern Coast of Arabia ... The gum resin. Olibanum', pp. 295-297", "not_counted_why": "Two reasons not to count it. Dymock reports the Mahometan writers rather than giving his own reading, and his own heading says the drug comes from several species of Boswellia growing in Africa and Arabia, none of them Boswellia serrata.", "note": "Two reasons not to count it. Dymock reports the Mahometan writers rather than giving his own reading, and his own heading says the drug comes from several species of Boswellia growing in Africa and Arabia, none of them Boswellia serrata.", "short": "Pharmacographia Indica I (1890)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. I", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0001/b21960343_0001_djvu.txt", "year": "1890"}, {"agreement": "Shown for context. Reported from Sanskrit writers rather than given by Dymock himself, and it describes the exudation as it flows fresh from the tree rather than the resin of the shops. Dymock's own identification is a conjecture: 'It seems probable that the true Sanskrit name for B. serrata is Sallaki', and he opens the article by saying the drug's history 'is involved in much obscurity, owing to its having been confounded by both native and European writers with true Frankincense and Bdellium'.", "assigns_moisture": "Moist", "assigns_temperature": null, "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Sanskrit writers describe Guggulu as moist, viscid, fragrant, and of a golden colour", "gloss": "Sanskrit writers call the exudation moist and viscid.", "locator": "Vol. I (1890), 'BOSWELLIA SERRATA, Roxb. Salai tree', p. 302", "not_counted_why": "Reported from Sanskrit writers rather than given by Dymock himself, and it describes the exudation as it flows fresh from the tree rather than the resin of the shops. Dymock's own identification is a conjecture: 'It seems probable that the true Sanskrit name for B. serrata is Sallaki', and he opens the article by saying the drug's history 'is involved in much obscurity, owing to its having been confounded by both native and European writers with true Frankincense and Bdellium'.", "note": "Reported from Sanskrit writers rather than given by Dymock himself, and it describes the exudation as it flows fresh from the tree rather than the resin of the shops. Dymock's own identification is a conjecture: 'It seems probable that the true Sanskrit name for B. serrata is Sallaki', and he opens the article by saying the drug's history 'is involved in much obscurity, owing to its having been confounded by both native and European writers with true Frankincense and Bdellium'.", "short": "Pharmacographia Indica I (1890)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. I", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0001/b21960343_0001_djvu.txt", "year": "1890"}, {"agreement": "Shown for context. This verse sits in the chapter of trees and describes the tree, not the resin the app entry is about, so it is set aside on the part rule. The name shallaki is tied to Boswellia serrata only by Dymock's 'it seems probable'.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "शल्लकी गजभक्ष्या च सुवहा सुरभी रसा महेरुणा कुन्दुरुकी वल्लकी च बहुस्रवा। शल्लकी तुवरा शीता पित्तश्लेष्मातिसारजित्", "gloss": "Shallaki, also called gajabhakshya, kunduruki and others: shallaki is astringent and COLD, and conquers pitta, kapha and diarrhoea.", "locator": "Bhavaprakasha Nighantu, Vatadi varga (the trees), verses 6.21-22 (bhava_ws offset 70507)", "not_counted_why": "This verse sits in the chapter of trees and describes the tree, not the resin the app entry is about, so it is set aside on the part rule. The name shallaki is tied to Boswellia serrata only by Dymock's 'it seems probable'.", "note": "This verse sits in the chapter of trees and describes the tree, not the resin the app entry is about, so it is set aside on the part rule. The name shallaki is tied to Boswellia serrata only by Dymock's 'it seems probable'.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Shown for context. This is the frankincense of the shops. The verse gives tastes and a sharpness but no temperature and no moisture, so there is nothing here to count even before the traded drug rule is applied.", "assigns_moisture": null, "assigns_temperature": null, "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "कुन्दुरुस्तु मुकुन्दः स्यात्सुगन्धः कुन्द इत्यपि। कुन्दुरुर्मधुरस्तिक्तस्तीक्ष्णस्त्वच्यः कटुर्हरेत् ज्वरस्वेदग्रहालक्ष्मीमुखरोगकफानिलान्", "gloss": "Kunduru, also called mukunda and sugandha: kunduru is sweet, bitter, sharp, good for the skin and pungent; it removes fever, sweating, seizure, ill luck, diseases of the mouth, kapha and vata.", "locator": "Bhavaprakasha Nighantu, Karpuradi varga, verses 3.49-50 (bhava_ws offset 27471)", "not_counted_why": "This is the frankincense of the shops. The verse gives tastes and a sharpness but no temperature and no moisture, so there is nothing here to count even before the traded drug rule is applied.", "note": "This is the frankincense of the shops. The verse gives tastes and a sharpness but no temperature and no moisture, so there is nothing here to count even before the traded drug rule is applied.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Shown for context. The Chinese ru xiang is imported olibanum, 'from the foreign countries' as Wu Yiluo says, and no plant is named. The same traded drug rule applies. Shown and not counted.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "乳香 一名熏陆香。宣、活血舒筋。苦溫。辛香善窜。入心。通行十二經。", "gloss": "Ru xiang, also called xun lu xiang: it disperses, moves the blood and relaxes the sinews. Bitter and WARM. Its pungent fragrance travels well. It enters the heart and passes through all twelve channels.", "locator": "卷七 木部, 乳香 (congxin.txt offset 75620)", "not_counted_why": "The Chinese ru xiang is imported olibanum, 'from the foreign countries' as Wu Yiluo says, and no plant is named. The same traded drug rule applies. Shown and not counted.", "note": "The Chinese ru xiang is imported olibanum, 'from the foreign countries' as Wu Yiluo says, and no plant is named. The same traded drug rule applies. Shown and not counted.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Drying", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H085 Bugleweed (1 source, shown, none counted)
insert into _energetics_batch6 values ('H085', $j${"agreement_state": "none", "app_value": {"moisture": "Drying", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Salmon 1710, Chap. CCCLXXVI 'Of HOREHOUND Water. Black Water Horehound': of the first kind, which is this plant, he writes 'As to the Qualities and Virtues of the first of these in this Chapter Authors have said nothing, but this I have found by experience, that it is an excellent Vulnerary'. No temperature and no moisture", "Rafinesque, Medical Flora (1828-30), No. 61 'LYCOPUS VIRGINICUS. Names. Bugleweed': a full article, but for the American Lycopus virginicus, a different species, and with no temperature or moisture", "Culpeper 1653: his 'Bugula, Bugle, or Middle Comfrey' is Ajuga reptans, a different plant altogether, and no Lycopus entry was found", "Schopf 1787, Dymock Vols. I-III, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Lycopus europaeus entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this reading. The one old writer only supposes it, and the other says plainly that nobody before him had written anything about the plant's qualities.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this reading. The one old writer only supposes it, and the other says plainly that nobody before him had written anything about the plant's qualities.", "The stored plant is Lycopus europaeus and the stored part is the aerial herb. Gerard's Water Horehound is this plant; his Names section gives it as Marrubium palustre and aquatile."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. 'It seemeth to be' hedges the reading in the same way as 'is thought to be', which the founder has already ruled does not count. Shown and not counted. The astringency is not a moisture in any case.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature. It seemeth to be cold, and withal very astringent or binding. The Virtues. There is little use of the Water Horehound in physic.", "gloss": "Water horehound seems to be cold and very binding.", "locator": "Book II, Chap. 234 'Of Water Horehound', The Temperature", "not_counted_why": "'It seemeth to be' hedges the reading in the same way as 'is thought to be', which the founder has already ruled does not count. Shown and not counted. The astringency is not a moisture in any case.", "note": "'It seemeth to be' hedges the reading in the same way as 'is thought to be', which the founder has already ruled does not count. Shown and not counted. The astringency is not a moisture in any case.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Drying", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

