insert into _energetics_batch6 values ('H086', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": true, "temperature": true}, "app_value_lines": {"moisture": "stored Slightly drying becomes Dry (stored value unclear; majority of first-hand sources, 2 of 2: Gerard (1633) dry; Salmon (1710) dry)", "temperature": "stored Warm (warming diaphoretic, paradoxically calming) becomes Warm (stored value unclear; majority of first-hand sources, 2 of 2: Gerard (1633) warm; Salmon (1710) warm)"}, "batch": 6, "checked_no_reading": ["Schopf 1787, Rafinesque 1828-30: no Nepeta cataria entry with a thermal quality", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Nepeta cataria entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what both counted writers give the degree for."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored value hedges and then explains itself, 'Warm (warming diaphoretic, paradoxically calming)'); majority of first-hand sources, 2 of 2: Gerard (1633) warm; Salmon (1710) warm. Moisture: stored value unclear (the stored value hedges itself, 'Slightly drying', so it is not a plain Dry); majority of first-hand sources, 2 of 2: Gerard (1633) dry; Salmon (1710) dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Nip is of temperature hot and dry, and hath the faculties of the Calamints.", "gloss": "Nep or catmint is hot and dry.", "locator": "Book II, Chap. 227 'Of Nip, or Catmint', The Temperature", "not_counted_why": "", "note": "No authority is named. The cross-reference to the calamints comes after the degree and adds nothing to it.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "XI. The Qualities. Nep or Cat-Mint is hot and dry in the third Degree; Aperitve, Abfterfive, Aftringent, Anodyn, Carminative, Digeftive, and Traumatick", "gloss": "Nep or cat-mint is hot and dry in the third degree.", "locator": "Chap. DXVII 'Of NEP; OR, CAT-MINT', The Qualities (OCR at offset 4180400; the chapter opens at offset 4177979)", "not_counted_why": "", "note": "Salmon gives the degree himself and names no authority. The OCR of this page is interleaved from two columns, but the degree sentence itself reads through cleanly.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. A cross-reference, and it is offered for the virtues rather than for the temperature. The chapter it points at, Mountain Calamint, is hot and dry in the third degree, but calamint is a different plant, and Nep appears in none of Culpeper's degree tables. Shown and not counted; raised as a question.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Cattaria, Nepeta. Nep, or Catmints. The virtues are the same with Calaminth.", "gloss": "Nep has the same virtues as calamint.", "locator": "Catalogue of simples, Herbs, 'Cattaria, Nepeta' (Gutenberg #49513, offset ~855438)", "not_counted_why": "A cross-reference, and it is offered for the virtues rather than for the temperature. The chapter it points at, Mountain Calamint, is hot and dry in the third degree, but calamint is a different plant, and Nep appears in none of Culpeper's degree tables. Shown and not counted; raised as a question.", "note": "A cross-reference, and it is offered for the virtues rather than for the temperature. The chapter it points at, Mountain Calamint, is hot and dry in the third degree, but calamint is a different plant, and Nep appears in none of Culpeper's degree tables. Shown and not counted; raised as a question.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}], "sources_agree": true, "stored_before": {"moisture": "Slightly drying", "temperature": "Warm (warming diaphoretic, paradoxically calming)"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself, 'Slightly drying', so it is not a plain Dry"}, "temperature": {"status": "unclear", "why": "the stored value hedges and then explains itself, 'Warm (warming diaphoretic, paradoxically calming)'"}}}$j$::jsonb);

-- H087 Coltsfoot (6 sources, SOURCES DISAGREE)
insert into _energetics_batch6 values ('H087', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": true, "temperature": true}, "app_value_lines": {"moisture": "stored Moistening (demulcent) becomes Dry (stored value unclear; majority of first-hand sources, 3 of 3: Culpeper (1653) dry; Salmon (1710) dry; Gerard (1633) dry)", "temperature": "stored Neutral to slightly warm becomes Warm (stored value unclear; first-hand sources tied 2 to 2; oldest source, Shennong Bencao Jing (c. 200 CE), reads warm)"}, "batch": 6, "checked_no_reading": ["Schopf 1787, Rafinesque 1828-30, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Tussilago farfara entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}, {"reading": "Dry", "source": "Gerard (1633)"}], "temperature": [{"reading": "Warm", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}, {"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, the old sources disagree: Shennong Bencao Jing (c. 200 CE) and Bencao Congxin (1757) read it as warm; Culpeper (1653) and Salmon (1710) read it as cold. The modern value was unclear and the counted sources are tied two to two, so the tie falls to the oldest first-hand written source, the Shennong Bencao Jing, and the app reads Warm. Gerard (1633) is shown but not counted on temperature, because he gives one reading for the green leaf and another for the dried leaf. On moisture, Gerard (1633), Culpeper (1653) and Salmon (1710) all read it as dry, and the modern value was unclear, so the app follows them and reads Dry.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the leaf and the flower. The three English writers give their degree for the leaf; the Chinese books give theirs for the flower, kuan dong hua, which is the same species, Tussilago farfara."], "part_used": "Leaf, Flower", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored value hedges between two readings, 'Neutral to slightly warm'); first-hand sources tied 2 to 2; oldest source, Shennong Bencao Jing (c. 200 CE), reads warm. Moisture: stored value unclear (the stored value hedges itself with a reason, 'Moistening (demulcent)'); majority of first-hand sources, 3 of 3: Culpeper (1653) dry; Salmon (1710) dry; Gerard (1633) dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "款冬花 味辛，溫。主咳逆上氣，善喘、喉痹，諸驚癇，寒熱邪氣。", "gloss": "Kuan dong hua: taste pungent, nature WARM. It treats cough with rebellious qi, wheezing, throat closure, frights and fits, and cold and heat from evil qi.", "locator": "草中品, 款冬花 (Sun Xingyan recension, shennong_sun.txt offset 47346)", "not_counted_why": "", "note": "Temperature only; the entry gives no moisture word. This is the oldest first-hand reading in the batch.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "款冬花 潤肺、化痰止嗽。辛溫潤肺。消痰除煩。定驚明目。治咳逆上氣喘渴。爲治嗽要藥。", "gloss": "Kuan dong hua: it moistens the lung, transforms phlegm and stops cough. Pungent and WARM, it moistens the lung, dissolves phlegm, settles vexation, calms fright and brightens the eyes.", "locator": "卷三 草部, 款冬花 (congxin.txt offset 43542)", "not_counted_why": "", "note": "Wu Yiluo writes his own compressed 'pungent and warm' rather than copying the Shennong sentence, so it counts; it agrees with the older reading it descends from. His run, moisten, is applied to the lung, so it is an action the drug performs and not a moisture of the drug itself. Temperature only.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Counted: differs from the app temperature (source cool, app warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Tussilago. Colt's-foot: something cold and dry, and therefore good for inflammations, they are admirably good for coughs, and consumptions of the lungs, shortness of breath", "gloss": "Coltsfoot is somewhat cold and dry.", "locator": "Catalogue of simples, Herbs, 'Tussilago' (Gutenberg #49513, offset ~898682); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~945500), where Coltsfoot is listed cold in the first degree and dry in the first degree", "not_counted_why": "", "note": "No authority is named. His tables agree with the entry, so he does not vote twice.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source cool, app warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. They are cold and dry in the firft Degree; Apperitive, Aftringent, Traumatick or Vulnerary, Pectoral, and Analeptick.", "gloss": "The coltsfoots are cold and dry in the first degree.", "locator": "Chap. CXLVII 'Of COLTS-FOOT', The Qualities (OCR at offset 1222900; the chapter opens at offset 1219857)", "not_counted_why": "", "note": "His sentence covers the two kinds he has just described, 'The true Colts-foot is either European or American', so it names each kind rather than speaking of a group. The European kind is Tussilago farfara, the stored plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Counted: agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Cold and hot, by the state of the leaf", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": false, "excerpt": "The leaves of Coltsfoot being fresh and green are something cold, and have withal a drying quality; they are good for ulcers and inflammations: but the dried leaves are hot and dry, and somewhat biting.", "gloss": "Fresh coltsfoot leaves are somewhat cold and drying; the dried leaves are hot and dry.", "locator": "Book II, Chap. 291 'Of Coltsfoot, or Horse-Foot', The Temperature and Virtues", "not_counted_why": "", "note": "Gerard gives two definite temperatures for the same part in two states, green and dried, so no single temperature reading can be taken from him and the temperature is not counted; this is raised as a question. He is plain and consistent on moisture, drying while green and dry when dried, so the moisture counts.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The heading and the whole indication list are marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "款冬花 ... 氣味辛温無毒 ... 主治欬逆上氣善喘喉痺諸驚癎寒熱邪氣 (本經)", "gloss": "Kuan dong hua: qi and flavour pungent, WARM, not toxic. Indications: cough with rebellious qi, wheezing, throat closure, frights and fits, cold and heat from evil qi.", "locator": "卷十六 草之五, 欵冬花, 氣味 (bcgm_16.txt offset 32100)", "not_counted_why": "The heading and the whole indication list are marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong.", "note": "The heading and the whole indication list are marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Moistening (demulcent)", "temperature": "Neutral to slightly warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a reason, 'Moistening (demulcent)'"}, "temperature": {"status": "unclear", "why": "the stored value hedges between two readings, 'Neutral to slightly warm'"}}}$j$::jsonb);

-- H088 Comfrey (3 sources, SOURCES DISAGREE)
insert into _energetics_batch6 values ('H088', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": true, "temperature": true}, "app_value_lines": {"moisture": "stored Moistening (demulcent) becomes Moist (stored value unclear; first-hand sources tied 1 to 1; oldest source, Gerard (1633), reads moist)", "temperature": "stored Cool to neutral becomes Cool (stored value unclear; majority of first-hand sources, 3 of 3: Gerard (1633) cool or cold; Culpeper (1653) cool or cold; Salmon (1710) cool or cold)"}, "batch": 6, "checked_no_reading": ["Salmon 1710, in his general preamble on glutinative medicines: 'They are also called Symphitica, which is the reason that Comfry is called Symphitum, because of its Glewing Quality. They are generally drying in the second degree.' That is a statement about a whole class of medicines, not about comfrey, so it is not counted", "Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Symphytum officinale entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Moist", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Cool", "source": "Gerard (1633)"}, {"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633), Culpeper (1653) and Salmon (1710) all read it as cold, and the modern value was unclear, so the app follows them and reads Cool. On moisture, the old sources disagree: Gerard (1633) reads it as moist, Salmon (1710) reads it as dry. The modern value was unclear and the two counted sources are tied one to one, so the tie falls to the older of them, Gerard, and the app reads Moist.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the root and the leaf. Gerard and Culpeper give their reading for the root; Salmon gives one reading for the plant and his preparations are made from root and leaves together."], "part_used": "Root, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored value hedges between two readings, 'Cool to neutral'); majority of first-hand sources, 3 of 3: Gerard (1633) cool or cold; Culpeper (1653) cool or cold; Salmon (1710) cool or cold. Moisture: stored value unclear (the stored value hedges itself with a reason, 'Moistening (demulcent)'); first-hand sources tied 1 to 1; oldest source, Gerard (1633), reads moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool); agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The root of Comfrey hath a cold quality, but yet not much: it is also of a clammy and glueing moisture, it causeth no itch at all, neither is it of a sharp or biting taste.", "gloss": "The comfrey root is cold, though not very cold, and is of a clammy and glueing moisture.", "locator": "Book II, Chap. 288 'Of Comfrey, or Great Confound', The Temperature", "not_counted_why": "", "note": "The moisture is given as a quality of the root itself, not as something the root does to a part of the body, so it counts. No authority is named.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Roots cold in the first degree. Sorrel, Beets, white and red, Comfrey the greater, Plantain, Rose Root, Madder.", "gloss": "Comfrey the greater is a root cold in the first degree.", "locator": "Culpeper's degree tables, 'Roots' (Gutenberg #49513, offset ~935300)", "not_counted_why": "", "note": "Comfrey is named on its own within the list, so it counts. Culpeper's catalogue entry, 'Consolida major. Comfrey, I do not conceive the leaves to be so virtuous as the roots', gives no degree and sends the reader to the roots. Comfrey appears in none of his dry or moist root tables, so this is a temperature only.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. It is cold and dry in the firft Degree: Aftringent, Anodyn, Repercuffive and Vulnerary : Neurotick, Peftoral, and Arthritick", "gloss": "Comfrey is cold and dry in the first degree.", "locator": "Chap. CXLIX 'Of COMFREY', The Qualities (OCR at offset 1247798; the chapter opens at offset 1238693)", "not_counted_why": "", "note": "Salmon gives the degree himself and names no authority. His chapter is Symphytum majus, the great comfrey, which is the stored plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Moistening (demulcent)", "temperature": "Cool to neutral"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a reason, 'Moistening (demulcent)'"}, "temperature": {"status": "unclear", "why": "the stored value hedges between two readings, 'Cool to neutral'"}}}$j$::jsonb);

-- H089 Corn Silk (1 source, shown, none counted)
insert into _energetics_batch6 values ('H089', $j${"agreement_state": "none", "app_value": {"moisture": "Moistening (mild demulcent diuretic)", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moistening (mild demulcent diuretic) (stored value unclear; no pre-1900 source found, so nothing to replace it)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Gerard 1633, Book I, Chap. 61 'Of Turkey Corn': 'We have as yet no certain proof or experience concerning the virtues of this kind of corn.' No temperature and no moisture", "Dymock, Pharmacographia Indica Vol. III (1893), 'ZEA MAYS, Linn. ... The stigmas and meal': 'In Greece the silky stigmata are used in decoction in diseases of the bladder, and have lately attracted attention in America under the name of Corn silk ... it has a marked diuretic action.' A use, not a temperature or a moisture; the properties he does report, 'resolvent, astringent, and very nourishing', are the Mahometan physicians' and are for the grain", "Schopf, Materia Medica Americana (1787), no. 283 'ZEA Mays': PHARM. Mays. Semina, Culmi; QVAL. 'Sem. farinacea. Culm. saccharina'. Mealy seed and sugary stalk, which is neither a temperature nor a moisture", "Culpeper 1653, Salmon 1710, Bencao Gangmu, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Porter Smith 1871: no corn silk entry with a thermal quality"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this part. The one old reading describes the grain, and this entry is about the silk.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this part. The one old reading describes the grain, and this entry is about the silk.", "The stored part is the silk, the stigmas of Zea mays. The one old reading with a temperature is for the grain."], "part_used": "Silk (stigma)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value unclear (the stored value hedges itself with a reason, 'Moistening (mild demulcent diuretic)'); no first-hand pre-1900 source found, so the stored value stays for now.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Wu Yiluo's sweet and neutral is given for the grain, which is what his entry is about; the white whiskers are only described, and the urinary use he names is for the root and leaves. The stored part is the silk, so this is set aside on the part rule.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "玉蜀黍 一名玉高粱。救荒。甘平。調中開胃。苞上出白須垂垂。根葉、治小便淋瀝沙石。痛不可忍。", "gloss": "Yu shu shu, also called yu gao liang, a famine food: sweet and NEUTRAL. It harmonises the centre and opens the appetite. From the husk white whiskers hang down. The root and leaves treat painful dribbling urine with gravel.", "locator": "卷十二 穀部, 玉蜀黍 (congxin.txt offset 117194)", "not_counted_why": "Wu Yiluo's sweet and neutral is given for the grain, which is what his entry is about; the white whiskers are only described, and the urinary use he names is for the root and leaves. The stored part is the silk, so this is set aside on the part rule.", "note": "Wu Yiluo's sweet and neutral is given for the grain, which is what his entry is about; the white whiskers are only described, and the urinary use he names is for the root and leaves. The stored part is the silk, so this is set aside on the part rule.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Moistening (mild demulcent diuretic)", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a reason, 'Moistening (mild demulcent diuretic)'"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

