insert into _energetics_batch6 values ('H090', $j${"agreement_state": "none", "app_value": {"moisture": "Neutral", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Gerard 1633, Book III, Chap. 78 'Of Marsh or Water Elder', which is Viburnum opulus: 'Concerning the faculties of these Elders, and the berries of the Water Elder, there is nothing found in any writer, neither can we set down anything hereof of our own knowledge.' He says plainly that there is nothing", "Rafinesque, Medical Flora (1828-30), s.v. VIBURNUM: 'Many sp. medical and useful', with uses for V. acerifolium, V. dentatum, V. prunifolium and others, but no temperature and no moisture anywhere", "Schopf 1787: no Viburnum entry found", "Culpeper 1653 and Salmon 1710: no Water Elder chapter with a degree was found", "Dymock Vols. I-III, Watt Vol. IV, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Viburnum opulus article"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": true, "notes": ["The stored part is the bark of Viburnum opulus."], "part_used": "Bark", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H091 Devil's Claw (0 sources, no qualifying source)
insert into _energetics_batch6 values ('H091', $j${"agreement_state": "none", "app_value": {"moisture": "Drying", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Culpeper 1653, Gerard 1633, Salmon 1710, Schopf 1787, Rafinesque 1828-30, Porter Smith 1871, Dutt 1877, Ibn al-Baytar (Leclerc Vols. I and II), Dymock Vols. I-III, Watt Vol. IV, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: the words Harpagophytum, Devil's Claw and Grapple Plant return nothing in any of them. The plant is southern African and reached European medicine in the twentieth century"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": true, "notes": ["The stored part is the secondary tuber of Harpagophytum procumbens, a plant of the Kalahari."], "part_used": "Root (secondary tuber)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Drying", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H092 Dong Quai (3 sources, sources agree)
insert into _energetics_batch6 values ('H092', $j${"agreement_state": "agree", "app_value": {"moisture": "Moistening (blood-building)", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moistening (blood-building) (stored value unclear; no pre-1900 source found, so nothing to replace it)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 6, "checked_no_reading": ["Culpeper 1653, Gerard 1633, Salmon 1710: no dang gui chapter (the plant is Chinese)", "Porter Smith 1871, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III, Dutt 1877: no Angelica sinensis entry with a thermal quality"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root, which is what all three Chinese books mean by dang gui."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value unclear (the stored value hedges itself with a reason, 'Moistening (blood-building)'); no first-hand pre-1900 source found, so the stored value stays for now.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "當歸 味甘，溫。主咳逆上氣，溫瘧、寒熱，洗在皮膚中，婦人漏下絕子，諸惡創瘍、金創。煮飲之。", "gloss": "Dang gui: taste sweet, nature WARM. It treats cough with rebellious qi, warm malaria with cold and heat, itching in the skin, women's flooding and barrenness, malign sores and wounds from metal. Boil it and drink it.", "locator": "草中品, 當歸 (Sun Xingyan recension, shennong_sun.txt offset 40898)", "not_counted_why": "", "note": "Temperature only; the entry gives no moisture word.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "當歸 補血、潤燥滑腸。甘溫和血。辛溫散内寒。苦溫助心散寒。入心肝脾。爲血中氣藥。", "gloss": "Dang gui: it supplements the blood, moistens dryness and lubricates the intestines. Sweet and WARM, it harmonises the blood; pungent and WARM, it scatters internal cold; bitter and WARM, it helps the heart to scatter cold. It enters heart, liver and spleen and is the qi medicine within the blood.", "locator": "卷二 草部, 當歸 (congxin.txt offset 21922)", "not_counted_why": "", "note": "Wu Yiluo writes his own three-part sentence rather than copying the Shennong line, so it counts; it agrees with the older reading it descends from. His run zao, moisten dryness, and hua chang, lubricate the intestines, are actions the drug performs on the body, not a moisture of the drug itself, so they are shown and not counted. Temperature only.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. The whole indication list is marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own added matter quotes other writers on the taste but gives no fresh degree.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "當歸 ... 氣味苦温無毒 ... 主治欬逆上氣温瘧寒熱汎汎在皮膚中婦人漏下絶子諸惡瘡瘍金瘡煑汁飲之 (本經)", "gloss": "Dang gui: qi and flavour bitter, WARM, not toxic. Indications: cough with rebellious qi, warm malaria with cold and heat, itching in the skin, women's flooding and barrenness, malign sores and wounds from metal. Boil the juice and drink it.", "locator": "卷十四 草之三 芳草類, 當歸, 氣味 (bcgm_14.txt offset 3277)", "not_counted_why": "The whole indication list is marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own added matter quotes other writers on the taste but gives no fresh degree.", "note": "The whole indication list is marked as taken from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own added matter quotes other writers on the taste but gives no fresh degree.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Moistening (blood-building)", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a reason, 'Moistening (blood-building)'"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H093 Elecampane (3 sources, sources agree)
insert into _energetics_batch6 values ('H093', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": true, "temperature": false}, "app_value_lines": {"moisture": "stored Slightly drying becomes Dry (stored value unclear; majority of first-hand sources, 3 of 3: Gerard (1633) dry; Culpeper (1653) dry; Salmon (1710) dry)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 6, "checked_no_reading": ["Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing: the Chinese xuan fu hua is Inula japonica and its relatives, not Inula helenium, so it was not used", "Schopf 1787, Rafinesque 1828-30, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Inula helenium entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root, which is what all three English writers give the degree for."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value unclear (the stored value hedges itself, 'Slightly drying', so it is not a plain Dry); majority of first-hand sources, 3 of 3: Gerard (1633) dry; Culpeper (1653) dry; Salmon (1710) dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The root of this Elecampane, is marvellous good for many things, being of nature hot and dry in the third degree, especially when it is dry: for being green and as yet full of juice, it is full of superfluous moisture, which somewhat abateth the hot and dry quality thereof.", "gloss": "The elecampane root is hot and dry in the third degree, most so when it is dried.", "locator": "Book II, Chap. 280 'Of Elecampane', The Temperature", "not_counted_why": "", "note": "No authority is named for the degree. He gives one reading and then explains that the fresh root's own juice abates it, which is a qualification of the same reading rather than a second one.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Hot in the third degree. Angelica, Aron, Birthwort long and round, Sowbread, Asarabacca, Briony, white and black, Sallendine, Virginian snakeroot, Hemeric, White Dittany, Doronicum, Hellebore, white and black, Elicampane; Dry in the third degree. Elicampane, Fillipendula, Galanga greater and lesser", "gloss": "Elecampane is a root hot in the third degree and dry in the third degree.", "locator": "Culpeper's degree tables, 'Roots' (Gutenberg #49513, offset ~935300)", "not_counted_why": "", "note": "Elecampane is named on its own within each list, so it counts. His catalogue entry, 'Enula Campana. Elicampane. Provokes urine. See the root', sends the reader to these tables.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VI. The Qualities. The Root is the chief thing which is ufed, and is hot and dry in the third De- gree", "gloss": "The elecampane root is hot and dry in the third degree.", "locator": "Chap. CCX 'Of ELECAMPANE', The Qualities (OCR at offset 1895000; the chapter opens at offset 1894705)", "not_counted_why": "", "note": "Salmon gives the degree himself and names no authority. The OCR of this page is interleaved from two columns, but the degree sentence reads through cleanly.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Slightly drying", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself, 'Slightly drying', so it is not a plain Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H094 Eyebright (3 sources, SOURCES DISAGREE)
insert into _energetics_batch6 values ('H094', $j${"agreement_state": "disagree", "app_value": {"moisture": "Drying", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 6, "checked_no_reading": ["Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Euphrasia entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633), Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what all three English writers give the degree for."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Nature. This herb is hot and dry, but yet more hot than dry.", "gloss": "Eyebright is hot and dry, and more hot than dry.", "locator": "Book II, Chap. 217 'Of Eyebright', The Nature", "not_counted_why": "", "note": "No authority is named. His Names and Description are Euphrasia, the stored plant.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Euphragia. Eyebright is something hot and dry, the very sight of it refresheth the eyes; inwardly taken, it restores the sight, and makes old men's eyes young", "gloss": "Eyebright is somewhat hot and dry.", "locator": "Catalogue of simples, Herbs, 'Euphragia' (Gutenberg #49513, offset ~865978); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~945500), where Eyebright is listed hot in the first degree and dry in the first degree", "not_counted_why": "", "note": "No authority is named. His tables agree with the entry, so he does not vote twice.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "ities. It is hot in the firft Degree md, and is efpecially appropriated gently Aftringent and Difcuffive.", "gloss": "Eyebright is hot in the first degree.", "locator": "Chap. CCXLVII 'Of EYE-BRIGHT', The Qualities (OCR at offset 1935100; the chapter opens at offset 1932201)", "not_counted_why": "", "note": "DAMAGED SCAN, reported and not reconstructed. This page is printed in two columns and the archive.org OCR has interleaved them, so the Qualities sentence runs into the Specification sentence of the other column. 'It is hot in the first Degree' reads through cleanly and is counted. The word that would carry the moisture cannot be separated from the other column's text, so no moisture is taken from Salmon.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Drying", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H095 Fenugreek (5 sources, sources agree)
insert into _energetics_batch6 values ('H095', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": true, "temperature": false}, "app_value_lines": {"moisture": "stored Moistening (mucilaginous when soaked) becomes Dry (stored value unclear; majority of first-hand sources; only one gives a reading: Culpeper (1653) dry)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 6, "checked_no_reading": ["Bhavaprakasha Nighantu, Haritakyadi varga, verses 2.92-94: methika is given a long list of synonyms and then 'methika vatashamani shleshmaghni jvaranashini', it calms vata, destroys kapha and destroys fever. There is no ushna or shita and no snigdha or ruksha in the verse, so there is nothing to count. The ruksha-ushna of verse 91 belongs to the herb before it, misreya", "Dutt, Materia Medica of the Hindus (1877), s.v. TRIGONELLA FOENUM-GRAECUM: 'Fenugreek seeds are considered carminative, tonic and aphrodisiac.' No temperature and no moisture", "Rajanighantu, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Schopf 1787, Rafinesque 1828-30: no fenugreek entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the seed. Culpeper's seed tables give the seed; Gerard, Salmon, Ibn al-Baytar and Dymock all hand the degree back to Galen or to other writers."], "part_used": "Seed", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value unclear (the stored value hedges itself with a condition, 'Moistening (mucilaginous when soaked)'); majority of first-hand sources; only one gives a reading: Culpeper (1653) dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Seeds are hot in the first degree. Linseed, Fenugreek, Coriander, Rice, Gromwell, Lupines. Dry in the first degree. Beans, Fennel, Fenugreek, Barley, Wheat, &c.", "gloss": "Fenugreek seed is hot in the first degree and dry in the first degree.", "locator": "Culpeper's degree tables, 'Seeds' (Gutenberg #49513, offset ~975449)", "not_counted_why": "", "note": "Fenugreek is named on its own within each list, so it counts. His prose entry under 'Seeds or Grains' calls the seeds 'of a softening, discussing nature' and gives no degree, so the tables are his only reading.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Two reasons not to count it. Galen is named inside the sentence, and 'It is thought' hedges it as well.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "It is thought according to Galen in his book Of The Faculties of Nourishments, that it is one of those simples which do manifestly heat, and that men do use it for food, as they do Lupins.", "gloss": "It is thought, on Galen's authority, that fenugreek manifestly heats.", "locator": "Book II, Chap. 500 'Of Fenugreek', The Temperature and Virtues", "not_counted_why": "Two reasons not to count it. Galen is named inside the sentence, and 'It is thought' hedges it as well.", "note": "Two reasons not to count it. Galen is named inside the sentence, and 'It is thought' hedges it as well.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Galen is named inside the sentence, so this is a report and not Salmon's own reading.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "VI. Ihe Qualities. Galen fays it is hot in the fecond Degree and dry in the firft : it is Aperitive, Cleanfing, Aftringent and Vulnerary", "gloss": "Galen says fenugreek is hot in the second degree and dry in the first.", "locator": "Chap. CCLVI 'Of FENUGREEK Garden', The Qualities (OCR at offset 2000700; the chapter opens at offset 1998635)", "not_counted_why": "Galen is named inside the sentence, so this is a report and not Salmon's own reading.", "note": "Galen is named inside the sentence, so this is a report and not Salmon's own reading.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Ibn al-Baytar opens the article by naming Galen, and everything that follows in it is quoted from Masserdjouih, Ibn Massouih and others. He gives no reading of his own here.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "unani", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Holba, Fenugrec. Galien, livre VIII. Il est chaud au second degre et sec au premier. C'est pourquoi il provoque les tumeurs inflammatoires.", "gloss": "Holba, fenugreek. Galen, book VIII: it is hot in the second degree and dry in the first.", "locator": "No. 682, Holba (Notices et extraits t. 23, pt. 1, p. 443; leclerc23.txt offset 1011594)", "not_counted_why": "Ibn al-Baytar opens the article by naming Galen, and everything that follows in it is quoted from Masserdjouih, Ibn Massouih and others. He gives no reading of his own here.", "note": "Ibn al-Baytar opens the article by naming Galen, and everything that follows in it is quoted from Masserdjouih, Ibn Massouih and others. He gives no reading of his own here.", "short": "Ibn al-Baytar, tr. Leclerc (1877)", "source": "Ibn al-Baytar, Traité des simples, tr. Lucien Leclerc, Vol. I (Notices et extraits des manuscrits, t. 23, pt. 1)", "tier": "second-hand-report", "tradition": "Unani (Arabic)", "url": "https://archive.org/download/NoticesEtExtraitsDesMss23P1/Notices_et_extraits_des_mss_23_p1_djvu.txt", "year": "1877"}, {"agreement": "Shown for context. Dymock reports the Mahometan writers rather than giving his own reading. Elsewhere in the same article he says the young leaves are eaten 'on account of their cooling properties', which is a use of the leaf and not a reading of the seed.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Under the Arabic name of Hulbah, and the Persian Shamlit, Mahometan writers describe the plant and seeds as hot and dry, suppurative, aperient, diuretic, emmenagogue", "gloss": "Mahometan writers describe fenugreek as hot and dry.", "locator": "Vol. I (1890), 'TRIGONELLA FOENUM-GRAECUM, Linn.', p. 402", "not_counted_why": "Dymock reports the Mahometan writers rather than giving his own reading. Elsewhere in the same article he says the young leaves are eaten 'on account of their cooling properties', which is a use of the leaf and not a reading of the seed.", "note": "Dymock reports the Mahometan writers rather than giving his own reading. Elsewhere in the same article he says the young leaves are eaten 'on account of their cooling properties', which is a use of the leaf and not a reading of the seed.", "short": "Pharmacographia Indica I (1890)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. I", "tier": "second-hand-report", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0001/b21960343_0001_djvu.txt", "year": "1890"}], "sources_agree": true, "stored_before": {"moisture": "Moistening (mucilaginous when soaked)", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a condition, 'Moistening (mucilaginous when soaked)'"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H096 Gentian (3 sources, SOURCES DISAGREE)
insert into _energetics_batch6 values ('H096', $j${"agreement_state": "disagree", "app_value": {"moisture": "Drying", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 6, "checked_no_reading": ["Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Gentiana lutea entry with a thermal quality (the Chinese long dan and the Indian gentians of Dymock Vol. II are other species)"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root of Gentiana lutea, the great gentian or great felwort."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Gentiana. Of Gentian; some call it Felwort, and Baldmoney. It is hot, cleansing, and scouring, a notable counterpoison, it opens obstructions, helps the biting of venemous beasts, and mad dogs, helps digestion", "gloss": "Gentian root is hot, cleansing and scouring.", "locator": "Catalogue of simples, Roots, 'Gentiana' (Gutenberg #49513, offset ~813288)", "not_counted_why": "", "note": "No authority is named. Gentian appears in none of Culpeper's dry or moist root tables, so this is a temperature only.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "XV. The Qualities. All the Gentians, both the Greater and the Smaller, are faid to be of one Pro- perty ... Gentian is hot and dry in the end of the fe- cond degree, Aperitive, Abfterfive, Aftringent, Car- minative, Diuretick", "gloss": "Gentian is hot and dry at the end of the second degree.", "locator": "Chap. CCCXII 'Of GENTIAN Small, OR, Small FELWORT', The Qualities (OCR at offset 2341837). His Chap. CCCXI 'Of GENTIAN Great, OR, Great FELWORT' refers the reader here for the qualities", "not_counted_why": "", "note": "The hedge, 'are said to be of one Property', governs the claim that the greater and the smaller gentians are alike; the degree sentence itself is given plainly and names no authority. He names both the Greater and the Smaller, and says the Greater 'are more used with us in Physick', so the reading reaches the stored plant, the great gentian.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Dioscorides is named inside the sentence, so this is a report and not Gerard's own reading.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The root of Felwort is hot, as Dioscorides saith, cleansing or scouring: divers copies have, that it is likewise binding, and of a bitter taste.", "gloss": "The gentian root is hot, as Dioscorides says.", "locator": "Book II, Chap. 105 'Of Felwort, or Baldmoney', The Temperature", "not_counted_why": "Dioscorides is named inside the sentence, so this is a report and not Gerard's own reading.", "note": "Dioscorides is named inside the sentence, so this is a report and not Gerard's own reading.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Drying", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H097 Gravel Root (0 sources, no qualifying source)
insert into _energetics_batch6 values ('H097', $j${"agreement_state": "none", "app_value": {"moisture": "Drying (diuretic)", "temperature": "Slightly warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (diuretic) (stored value unclear; no pre-1900 source found, so nothing to replace it)", "temperature": "stays Slightly warm (stored value unclear; no pre-1900 source found, so nothing to replace it)"}, "batch": 6, "checked_no_reading": ["Rafinesque, Medical Flora (1828-30), No. 36, second species: 'E. purpureum or Purple Boneset (Joepye, Gravel root, &c.) ... It has the same properties as E. perfoliatum, has been used in fevers and gravel, &c.' The right plant under the right English name, but no temperature and no moisture; the book gives none anywhere", "Schopf, Materia Medica Americana (1787): no Eupatorium entry found", "Culpeper 1653, Gerard 1633, Salmon 1710: no chapter (the plant is American)", "Dymock Vols. I-III, Watt Vol. IV, Dutt 1877, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Eupatorium purpureum article"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": true, "notes": ["The stored part is the root of Eutrochium purpureum, the purple boneset or joe-pye weed."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored value hedges itself, 'Slightly warm', so it is not a plain Warm); no first-hand pre-1900 source found, so the stored value stays for now. Moisture: stored value unclear (the stored value hedges itself with a reason, 'Drying (diuretic)'); no first-hand pre-1900 source found, so the stored value stays for now.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Drying (diuretic)", "temperature": "Slightly warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored value hedges itself with a reason, 'Drying (diuretic)'"}, "temperature": {"status": "unclear", "why": "the stored value hedges itself, 'Slightly warm', so it is not a plain Warm"}}}$j$::jsonb);

-- H098 Ground Ivy (3 sources, sources agree)
insert into _energetics_batch6 values ('H098', $j${"agreement_state": "agree", "app_value": {"moisture": "Drying", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": true}, "app_value_lines": {"moisture": "stays Drying (clear modern value; old sources agree)", "temperature": "stored Warm (slightly) becomes Warm (stored value unclear; majority of first-hand sources, 3 of 3: Gerard (1633) warm; Culpeper (1653) warm; Salmon (1710) warm)"}, "batch": 6, "checked_no_reading": ["Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Glechoma hederacea entry with a thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what all three English writers give the degree for."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored value hedges itself, 'Warm (slightly)', so it is not a plain Warm); majority of first-hand sources, 3 of 3: Gerard (1633) warm; Culpeper (1653) warm; Salmon (1710) warm. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Ground-Ivy is hot and dry, and because it is bitter it scoureth, and removeth stoppings out of the entrails.", "gloss": "Ground ivy is hot and dry.", "locator": "Book II, Chap. 315 'Of Ground-Ivy, or Ale-Hoof', The Temperature", "not_counted_why": "", "note": "No authority is named for the degree. Matthiolus, Dioscorides and Galen are named further down for particular uses, not for the temperature.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Ground-Ivy is that which usually is called Alehoof, hot and dry, the juice helps noise in the ears, fistulas, gouts, stoppings of the liver, it strengthens the reins and stops the menses", "gloss": "Ground ivy, or alehoof, is hot and dry.", "locator": "Catalogue of simples, Herbs, 'Hedera Arborea, Terrostris' (Gutenberg #49513, offset ~869131); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~945500), where Ale-hoof is listed hot in the second degree and dry in the second degree", "not_counted_why": "", "note": "No authority is named. His tables agree with the entry, so he does not vote twice.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. They are all of one nature, hot and dry in the firft degree: but the two latter are dry in the fecond degree. They are Aperitive, Abfterfive, Bechicick, Attenuaters and Vulnerary", "gloss": "The ground ivies are all of one nature, hot and dry in the first degree, though the last two are dry in the second.", "locator": "Chap. VI 'Of ALEHOOF, Great, Small, &c.', The Qualities (OCR at offset 183100; the chapter opens at offset 181686)", "not_counted_why": "", "note": "Salmon has just named his four kinds one by one, all of them Hedera terrestris, and the first is 'the Common Ground Ivy, or Alehoof', the stored plant. Because he names each kind rather than speaking of a group, and because he separates out 'the two latter', the reading reaches the common ground ivy directly.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Drying", "temperature": "Warm (slightly)"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "unclear", "why": "the stored value hedges itself, 'Warm (slightly)', so it is not a plain Warm"}}}$j$::jsonb);

-- H099 Gymnema (1 source, sources agree)
insert into _energetics_batch6 values ('H099', $j${"agreement_state": "agree", "app_value": {"moisture": "Drying", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Drying (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Dymock, Pharmacographia Indica Vol. II (1891), 'GYMNEMA SYLVESTRE, Br.': he reports the Nighantu account, 'described as having a pungent taste and the properties of an astringent and bitter stomachic; useful in cough, biliousness, boils, sore eyes', which is a report and carries no temperature or moisture of its own. He also notes the plant 'is not mentioned in the Raja Nirghanta'", "Dutt 1877: Gymnema sylvestre appears only in the glossary of Indian plants, with no article", "Culpeper 1653, Gerard 1633, Salmon 1710, Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Rajanighantu, Ibn al-Baytar (Leclerc Vols. I and II): no Gymnema entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Bhavaprakasha (16th c.)"}], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the leaf. The Bhavaprakasha verse is for the plant, and a following verse treats the fruit separately."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Drying), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: shown on moisture as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": "Dry", "assigns_temperature": null, "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": false, "excerpt": "मेषशृङ्गी विषाणी स्यान्मेषवल्ल्यजशृङ्गिका। मेषशृङ्गी रसे तिक्ता वातला श्वासकासहृत् रूक्षा पाके कटुः पित्तव्रणश्लेष्माक्षिशूलनुत्", "gloss": "Meshashringi, also called vishani, meshavalli and ajashringika: meshashringi is bitter in taste, raises vata and removes wheezing and cough; it is RUKSHA (DRY), pungent after digestion, and removes pitta, wounds, kapha and pain in the eyes.", "locator": "Bhavaprakasha Nighantu, Guduchyadi varga, verses 4.252-253 (bhava_ws offset 57354)", "not_counted_why": "", "note": "Ruksha is the drug's own quality, not an action it performs, so it counts as Dry. The verse gives no ushna and no shita, so there is no temperature here. Dymock, Pharmacographia Indica Vol. II (1891), p. 450, confirms the plant: 'This shrubby climbing plant is called Meshasringi, ram's horn, in Sanskrit ... It is considered to be the Meshasringi of Madanpal's Nighanta.'", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}], "sources_agree": true, "stored_before": {"moisture": "Drying", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Drying"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

