insert into _energetics_batch6 values ('H100', $j${"agreement_state": "none", "app_value": {"moisture": "Neutral", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; no pre-1900 source found)"}, "batch": 6, "checked_no_reading": ["Dymock, Pharmacographia Indica Vol. III (1893), 'HERPESTIS MONNIERA, H. B. et K.': the right plant, with its vernacular names and its uses in insanity and epilepsy, but no temperature and no moisture of its own", "Dutt, Materia Medica of the Hindus (1877), 'HERPESTIS MONNIERA': 'The herb used by the native physicians of Calcutta under the name of brahmi is the Herpestis Monniera ... This plant is considered a nervine tonic, useful in insanity, epilepsy and hoarseness.' He records the same name problem, noting that Roxburgh gives brahmi for Ruta graveolens. No temperature and no moisture", "Rajanighantu: no brahmi verse found", "Culpeper 1653, Gerard 1633, Salmon 1710, Schopf 1787, Rafinesque 1828-30, Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Ibn al-Baytar (Leclerc Vols. I and II): no Bacopa entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The Sanskrit brahmi of the old dictionaries is a different plant, and the writers who do describe this one give no temperature or moisture.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this exact plant. The Sanskrit brahmi of the old dictionaries is a different plant, and the writers who do describe this one give no temperature or moisture.", "The stored plant is Bacopa monnieri, known in the nineteenth century as Herpestis monniera and Gratiola monnieria. The Sanskrit name brahmi is the trap: the Nighantus use it for a different plant."], "part_used": "Aerial Parts / Whole Herb", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Set aside as a different species, on first-hand pre-1900 evidence. Dymock, Pharmacographia Indica Vol. III (1893), p. 8, writes of Herpestis monniera: 'It is certainly not the Brahmi of the Nighantas, but would appear to be the plant called Jala-brahmi or Water Brahmi by Sanskrit writers. Owing to a similarity in the names it has frequently been confounded with Hydrocotyle asiatica, which is the Brahmi or Brahmi-manduka of the Nighantas.' The verse itself bears him out: it lists mandukaparni and manduki among brahmi's own names, and closes 'tadvan mandukaparnini', mandukaparni likewise. The Bhavaprakasha also uses the name a third way at 10.27, where brahmi is hilamochika, a pot-herb. Shown and counted for nothing.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "ब्राह्मी कपोतवङ्का च सोमवल्ली सरस्वती मण्डूकपर्णी माण्डूकी त्वाष्ट्री दिव्या महौषधी। ब्राह्मी हिमा सरा तिक्ता लघुर्मध्या च शीतला कषाया मधुरा स्वादुपाकाऽयुष्या रसायनी", "gloss": "Brahmi, also called kapotavanka, somavalli, sarasvati, MANDUKAPARNI, manduki, tvashtri, divya and mahaushadhi: brahmi is HIMA (COLD), flowing, bitter, light, middling and SHITALA (COOLING), astringent and sweet, sweet after digestion, life-giving and rejuvenating.", "locator": "Bhavaprakasha Nighantu, Guduchyadi varga, verses 4.278-280 (bhava_ws offset 59597)", "not_counted_why": "Set aside as a different species, on first-hand pre-1900 evidence. Dymock, Pharmacographia Indica Vol. III (1893), p. 8, writes of Herpestis monniera: 'It is certainly not the Brahmi of the Nighantas, but would appear to be the plant called Jala-brahmi or Water Brahmi by Sanskrit writers. Owing to a similarity in the names it has frequently been confounded with Hydrocotyle asiatica, which is the Brahmi or Brahmi-manduka of the Nighantas.' The verse itself bears him out: it lists mandukaparni and manduki among brahmi's own names, and closes 'tadvan mandukaparnini', mandukaparni likewise. The Bhavaprakasha also uses the name a third way at 10.27, where brahmi is hilamochika, a pot-herb. Shown and counted for nothing.", "note": "Set aside as a different species, on first-hand pre-1900 evidence. Dymock, Pharmacographia Indica Vol. III (1893), p. 8, writes of Herpestis monniera: 'It is certainly not the Brahmi of the Nighantas, but would appear to be the plant called Jala-brahmi or Water Brahmi by Sanskrit writers. Owing to a similarity in the names it has frequently been confounded with Hydrocotyle asiatica, which is the Brahmi or Brahmi-manduka of the Nighantas.' The verse itself bears him out: it lists mandukaparni and manduki among brahmi's own names, and closes 'tadvan mandukaparnini', mandukaparni likewise. The Bhavaprakasha also uses the name a third way at 10.27, where brahmi is hilamochika, a pot-herb. Shown and counted for nothing.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

do $do$
declare
  rec record;
  n int;
  written int := 0;
  skipped int := 0;
begin
  for rec in select herb_id, citation from _energetics_batch6 order by herb_id loop
    update public.herbs h
       set energetics_citation = rec.citation,
           last_updated = now()
     where h.herb_id = rec.herb_id
       and h.energetics_citation is distinct from rec.citation
       and (h.energetics_citation is null or h.energetics_citation ? 'batch');
    get diagnostics n = row_count;
    if n = 1 then
      written := written + 1;
    else
      if exists (select 1 from public.herbs
                  where herb_id = rec.herb_id and energetics_citation = rec.citation) then
        skipped := skipped + 1;
      else
        raise exception '%.energetics_citation: live value is neither NULL nor a batch object (or the herb is missing); not overwritten', rec.herb_id;
      end if;
    end if;
  end loop;
  raise notice 'energetics batch 6: %s written, %s already current', written, skipped;
end
$do$;

-- -----------------------------------------------------------------------------
-- 2. Verification. Any failure aborts the whole transaction.
-- -----------------------------------------------------------------------------
do $do$
declare
  bad text[] := '{}';
  n int;
  moved text;
begin
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 6;
  if n <> 25 then bad := bad || ('batch 6 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs where energetics_citation ? 'batch';
  if n <> 150 then bad := bad || ('batch citations in total: ' || n || ', expected 150'); end if;
  select count(*) into n from public.herbs
   where energetics_citation is not null and not (energetics_citation ? 'batch');
  if n <> 69 then bad := bad || ('legacy single-source citations: ' || n || ', expected 69'); end if;

  -- Every batch herb has a sources array or the honest no-source flag, and every
  -- stored source carries the fields the page renders.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (jsonb_typeof(energetics_citation->'sources') = 'array'
          or (energetics_citation->>'no_pre1900_source_found')::boolean);
  if n <> 150 then bad := bad || ('batch herbs with a sources array or the no-source flag: ' || n || ', expected 150'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0
     and not (energetics_citation->>'no_pre1900_source_found')::boolean;
  if n <> 0 then bad := bad || (n || ' herb(s) have no source and no no-source flag'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch' and coalesce(energetics_citation->>'rule', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) carry no basis line'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch';
  if n <> 368 then bad := bad || ('stored sources: ' || n || ', expected 368'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s ? 'source' and s ? 'year' and s ? 'corpus' and s ? 'tier'
              and s ? 'assigns_temperature' and s ? 'assigns_moisture'
              and s ? 'excerpt' and s ? 'locator' and s ? 'url'
              and s ? 'agreement' and s ? 'counted');
  if n <> 0 then bad := bad || (n || ' source(s) are missing a required field'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s->>'counted')::boolean
     and coalesce(s->>'not_counted_why', '') = '';
  if n <> 0 then bad := bad || (n || ' uncounted source(s) do not say why they were not counted'); end if;

  -- Never claim agreement the data does not carry.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'agreement_state' = 'disagree'
     and coalesce(energetics_citation->>'disagreement_text', '') = '';
  if n <> 0 then bad := bad || (n || ' disagreeing herb(s) carry no disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and coalesce(energetics_citation->>'disagreement_text', '') <> '';
  if n <> 0 then bad := bad || (n || ' agreeing herb(s) also carry a disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0;
  if n <> 0 then bad := bad || (n || ' herb(s) claim agreement with no sources at all'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'disagreement_text' like '%' || chr(8212) || '%';
  if n <> 0 then bad := bad || (n || ' disagreement sentence(s) contain an em dash'); end if;

  -- Sources found but none counted: the herb must say why, and a herb that DID
  -- count a source must never carry that line.
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean);
  if n <> 26 then bad := bad || ('herbs with sources but none counted: ' || n || ', expected 26'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean)
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) counted no source and say nothing about why'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') <> ''
     and exists (select 1 from jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
                  where (s->>'counted')::boolean);
  if n <> 0 then bad := bad || (n || ' herb(s) claim no counted source while showing one'); end if;

  -- 3. EXACTLY the approved values moved, and nothing else did. Each is checked
  --    by its final value, then the whole table is checked for strays.
  select temperature into moved from public.herbs where herb_id = 'H077';
  if moved is distinct from 'Warm' then
    bad := bad || ('H077 temperature is ' || coalesce(moved, 'NULL') || ', expected Warm');
  end if;
  select temperature into moved from public.herbs where herb_id = 'H086';
  if moved is distinct from 'Warm' then
    bad := bad || ('H086 temperature is ' || coalesce(moved, 'NULL') || ', expected Warm');
  end if;
  select moisture into moved from public.herbs where herb_id = 'H086';
  if moved is distinct from 'Dry' then
    bad := bad || ('H086 moisture is ' || coalesce(moved, 'NULL') || ', expected Dry');
  end if;
  select temperature into moved from public.herbs where herb_id = 'H087';
  if moved is distinct from 'Warm' then
    bad := bad || ('H087 temperature is ' || coalesce(moved, 'NULL') || ', expected Warm');
  end if;
  select moisture into moved from public.herbs where herb_id = 'H087';
  if moved is distinct from 'Dry' then
    bad := bad || ('H087 moisture is ' || coalesce(moved, 'NULL') || ', expected Dry');
  end if;
  select temperature into moved from public.herbs where herb_id = 'H088';
  if moved is distinct from 'Cool' then
    bad := bad || ('H088 temperature is ' || coalesce(moved, 'NULL') || ', expected Cool');
  end if;
  select moisture into moved from public.herbs where herb_id = 'H088';
  if moved is distinct from 'Moist' then
    bad := bad || ('H088 moisture is ' || coalesce(moved, 'NULL') || ', expected Moist');
  end if;
  select moisture into moved from public.herbs where herb_id = 'H093';
  if moved is distinct from 'Dry' then
    bad := bad || ('H093 moisture is ' || coalesce(moved, 'NULL') || ', expected Dry');
  end if;
  select moisture into moved from public.herbs where herb_id = 'H095';
  if moved is distinct from 'Dry' then
    bad := bad || ('H095 moisture is ' || coalesce(moved, 'NULL') || ', expected Dry');
  end if;
  select temperature into moved from public.herbs where herb_id = 'H098';
  if moved is distinct from 'Warm' then
    bad := bad || ('H098 temperature is ' || coalesce(moved, 'NULL') || ', expected Warm');
  end if;
  select count(*), string_agg(h.herb_id, ', ' order by h.herb_id) into n, moved
    from public.herbs h join _energetics_before_b6 b using (herb_id)
   where h.temperature is distinct from b.temperature
      or h.moisture is distinct from b.moisture;
  if n <> 7 or moved <> 'H077, H086, H087, H088, H093, H095, H098' then
    bad := bad || ('energetics moved on ' || n || ' herb(s): ' || coalesce(moved, 'none') || '; expected exactly H077, H086, H087, H088, H093, H095, H098');
  end if;
  select count(*) into n from public.herbs;
  if n <> (select count(*) from _energetics_before_b6) then
    bad := bad || 'the herb count changed'::text;
  end if;
  select count(*) into n from public.herb_energetics_evidence_v;
  if n <> 150 then bad := bad || ('herb_energetics_evidence_v rows: ' || n || ', expected 150'); end if;

  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 6: checks failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

-- 4. The tier gate, proved by READING the view as anon rather than by reading its
--    definition. A blind check that returns nothing looks healthy, so this asserts
--    a NON-EMPTY free result and a NULL source list together.
do $do$
declare
  bad text[] := '{}';
  free_text text;
  src jsonb;
  seen int;
begin
  begin
    set local role anon;
  exception when insufficient_privilege then
    raise notice 'cannot SET ROLE anon here; the functional tier check was skipped';
    return;
  end;
  select count(*) into seen from public.herb_energetics_evidence_v;
  if seen <> 150 then bad := bad || ('anon sees ' || seen || ' evidence rows, expected 150'); end if;
  select disagreement_text, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H087';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the disagreement sentence on H087'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H087'::text;
  end if;
  select no_counted_source_line into free_text
    from public.herb_energetics_evidence_v where herb_id = 'H076';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the no-counted-source line on H076'::text;
  end if;
  if (select no_pre1900_source_found from public.herb_energetics_evidence_v
       where herb_id = 'H078') is not true then
    bad := bad || 'anon cannot read the no-source flag on H078'::text;
  end if;
  reset role;
  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 6: tier gate failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

commit;
